mapper.select:
SELECT , u.real_name AS counselor_name FROM visitor_log v LEFT JOIN sys_user u ON v.counselor_id = u.id
AND v.visitor_name LIKE CONCAT('%', #{visitorName}, '%') AND v.status = #{status} AND v.counselor_id = #{counselorId}
ORDER BY v.visit_time DESC, v.id DESC

mapper.update:
UPDATE visitor_log
visitor_name = #{visitorName}, phone = #{phone}, id_card = #{idCard}, visit_purpose = #{visitPurpose}, visit_object = #{visitObject}, visit_time = #{visitTime}, leave_time = #{leaveTime}, status = #{status}, counselor_id = #{counselorId},
WHERE id = #{id}
